import { DOCUMENT, Location, isPlatformBrowser } from '@angular/common';
import { Component, DestroyRef, Inject, OnInit, PLATFORM_ID, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { NavigationEnd, ActivatedRoute, Router, RouterOutlet } from '@angular/router';
import { filter } from 'rxjs/operators';
import { HeaderComponent } from './shared/header/header.component';
import { FooterComponent } from './shared/footer/footer.component';
import { SeoMetadata, SeoService } from './core/services/seo.service';
import { PageSeoService } from './core/services/page-seo.service';
import { AosService } from './core/services/aos.service';

@Component({
  selector: 'app-root',
  imports: [RouterOutlet, HeaderComponent, FooterComponent],
  templateUrl: './app.html',
  styleUrls: ['./app.scss']
})
export class App implements OnInit {
  protected readonly title = signal('pixtar-website');
  private readonly destroyRef = inject(DestroyRef);
  private readonly isBrowser: boolean;

  constructor(
    private readonly router: Router,
    private readonly route: ActivatedRoute,
    private readonly seoService: SeoService,
    private readonly pageSeoService: PageSeoService,
    private readonly aosService: AosService,
		public location: Location,
    @Inject(PLATFORM_ID) private platformId: Object,
    @Inject(DOCUMENT) private readonly document: Document,
  ) {
    this.isBrowser = isPlatformBrowser(platformId);
  }

  ngOnInit(): void {
    this.applyRouteSeo();
    if (this.isBrowser) {
    // ✅ INIT AOS ONCE
    this.aosService.ensureInitialized().then(() => {
      this.aosService.refresh(); // first load
    });
  }

    this.router.events
      .pipe(
        filter((event): event is NavigationEnd => event instanceof NavigationEnd),
        takeUntilDestroyed(this.destroyRef)
      )
      .subscribe(() => {
        this.applyRouteSeo();
        if (this.isBrowser) {
          // Use refreshPageAnimation for route changes to ensure proper reset
          this.aosService.ensureInitialized().then(() => {
            this.aosService.refreshPageAnimation();

            // Additional fallback refresh for edge cases
            setTimeout(() => this.aosService.refreshPageAnimation(), 500);
          });
        }
      });
  }

  private applyRouteSeo(): void {
    const activeRoute = this.getActiveRoute();

    const seo = activeRoute?.snapshot.data?.['seo'] as SeoMetadata | undefined;
    if (!seo) {
      return;
    }

    const currentPath = this.router.url.split(/[?#]/)[0] || '/';
    const canonicalPath = this.resolveCanonicalPath(seo.canonicalPath ?? currentPath, currentPath);
    this.seoService.apply({
      ...seo,
      canonicalPath
    });

    const pageSeoName = this.getPageSeoName(activeRoute);
    if (!pageSeoName) {
      return;
    }

    this.pageSeoService.getPageSeo(pageSeoName)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe((apiSeo) => {
        if (!apiSeo) {
          return;
        }

        this.seoService.apply({
          ...seo,
          ...apiSeo,
          canonicalPath
        });
      });
  }

  private getPageSeoName(activeRoute: ActivatedRoute | null): string | undefined {
    const routeParamName = activeRoute?.snapshot.paramMap?.get('url_key');
    if (routeParamName) {
      return routeParamName;
    }

    return activeRoute?.snapshot.data?.['pageSeoName'] as string | undefined;
  }

  // Every route's static `canonicalPath` (app.routes.ts) is defined once and shared
  // between the English tree and the `/ar` tree via createSiteRoutes(), so it never
  // carries the `/ar` prefix on its own. Without this, every Arabic page declared its
  // canonical as the English URL, telling Google to index the English page instead.
  private resolveCanonicalPath(basePath: string, currentPath: string): string {
    const isArabic = currentPath === '/ar' || currentPath.startsWith('/ar/');
    if (!isArabic || basePath.startsWith('/ar')) {
      return basePath;
    }
    return basePath === '/' ? '/ar' : `/ar${basePath}`;
  }

  onActivate(): void {
    if (!this.isBrowser) {
      return;
    }

    // Use multiple attempts with increasing delays to ensure DOM is ready
    this.aosService.ensureInitialized().then(() => {
      // Immediate refresh
      this.aosService.refreshPageAnimation();

      // Additional refreshes with delays to catch late-rendered content
      setTimeout(() => this.aosService.refreshPageAnimation(), 100);
      setTimeout(() => this.aosService.refreshPageAnimation(), 300);
      setTimeout(() => this.aosService.refreshPageAnimation(), 600);
    });
  }

  private getActiveRoute(): ActivatedRoute | null {
    let activeRoute = this.route.firstChild;

    while (activeRoute?.firstChild) {
      activeRoute = activeRoute.firstChild;
    }

    return activeRoute ?? null;
  }

  removeFooter(): boolean {
		const path = this.location.prepareExternalUrl(this.location.path()).slice(1);
		const noFooterRoutes = ['/signup', '/nucleoicons', 'p/kbn', 'p/kbn2', 'p/js', 'p/io', 'p/godly'];
		return !noFooterRoutes.some(route => path.includes(route));
	}
  removeHeader(): boolean {
		const path = this.location.prepareExternalUrl(this.location.path()).slice(1);
		const noHeaderRoutes = ['p/kbn', 'p/kbn2', 'p/js', 'p/io', 'p/godly'];
		const hideHeader = noHeaderRoutes.includes(path);
		if (!this.isBrowser) {
			return !hideHeader;
		}

		const botPenguinLauncher = this.document.getElementById('botpenguin-launcher-12');

		if (hideHeader && botPenguinLauncher?.classList.contains('botpenguin-right')) {
			const botChat = this.document.querySelector('.BotPenguin-chat');
			if (botChat) {
				botChat.classList.add('d-none');
			}
		}

		return !hideHeader;
	}
}
