import { Component, OnInit } from '@angular/core';
import { Location, DatePipe } from '@angular/common';
import { environment } from '../../../environments/environment';
import { LucideAngularModule } from 'lucide-angular';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import { TranslationService } from '../../core/services/translation.service';

@Component({
  selector: 'app-footer',
  standalone: true,
  imports: [RouterModule, CommonModule, DatePipe, LucideAngularModule],
  templateUrl: './footer.component.html',
  styleUrl: './footer.component.scss'
})
export class FooterComponent implements OnInit {
  baseUrl: any;
  imagePath: any;
  test: Date = new Date();
  isfooterBlack: boolean = false;
  constructor(public location: Location,
    public translationService: TranslationService
  ) {
    this.imagePath = environment.baseUrl + '/public/';
    this.baseUrl = environment.url;
  }
  ngOnInit() {
  }
  removeFooter() {
    this.isfooterBlack = false;
    var _location = this.location.path();
    _location = _location.split('/')[1];
    if (_location == 'projects' || _location == 'about') {
      this.isfooterBlack = true;
      return true;
    } else {
      return false;
    }
  }
}
